    /// <summary>
    /// A unit-of-work base class that buffers configuration changes and writes only modified properties to disk.
    /// </summary>
    /// <remarks>
    /// The dirty settings set is tracked in <see cref="_dirtySettings"/>. Changes are only persisted when
    /// <see cref="SaveChanges"/> is explicitly called, or automatically when the configuration service disposes.
    /// This pattern avoids unnecessary disk writes during temporary operations and ensures only modified values
    /// are saved.
    /// </remarks>
    public abstract class ConfigDirtySaver
    {

        /// <summary>Tracks settings that have been modified but not yet persisted.</summary>
        protected readonly HashSet<ISettingBase> _dirtySettings = [];

        /// <summary>Marks a setting as dirty so it will be saved on the next <see cref="SaveChanges"/> call.</summary>
        /// <param name="setting">The setting that was modified.</param>
        protected void MarkDirty(ISettingBase setting)
            => _dirtySettings.Add(setting);

        /// <summary>Gets whether any settings have been modified but not yet saved.</summary>
        protected bool HasChanges => _dirtySettings.Count > 0;

        /// <summary>Persists all dirty settings to the configuration service.</summary>
        /// <param name="configService">The configuration service used to save values.</param>
        protected void SaveChanges(IConfigService configService)
        {
            if (!HasChanges) return;

            foreach (ISettingBase setting in _dirtySettings)
                configService.SaveConfigValue(setting);

            _dirtySettings.Clear();
        }

        /// <summary>Initializes a configuration setting with a default value if it has not already been set.</summary>
        /// <typeparam name="T">The type of the setting, must implement <see cref="ISettingBase"/>.</typeparam>
        /// <param name="name">The name/key of the configuration setting.</param>
        /// <param name="setting">The setting instance, either retrieved or newly created.</param>
        /// <param name="configService">The configuration service used to initialize the setting.</param>
        /// <param name="package">The content package containing the setting definition.</param>
        /// <returns><c>true</c> if the setting was initialized; <c>false</c> if it already existed.</returns>
        protected bool TryInitConfig<T>(string name, out T setting, IConfigService configService, ContentPackage package) where T : ISettingBase
            => ConfigHelper.TryInitConfig<T>(name, out setting, configService, package, MarkDirty);
    }

    /// <summary>
    /// Provides helper methods for configuration management, including loading, saving, and resetting configs.
    /// </summary>
    /// <remarks>
    /// All operations iterate over configs retrieved via <c>API.GetAllConfigs()</c>.
    /// Errors during individual config operations are logged via <see cref="Logger"/> and execution continues
    /// to the next config (no single failure stops the entire operation).
    /// </remarks>
    public static class ConfigHelper
    {
        #region Loader configs

        /// <summary>
        /// Loads all registered configurations by calling <see cref="ISOSConfig.Load"/> on each one.
        /// </summary>
        /// <remarks>
        /// Iterates over all configs retrieved via <c>API.GetAllConfigs()</c>.
        /// If a config's <see cref="ISOSConfig.Load"/> throws an exception, it is caught, logged via
        /// <see cref="Logger.LogError"/>, and execution continues to the next config.
        /// </remarks>
        public static void LoadConfigs()
        {
            foreach (var config in API.GetAllConfigs())
            {
                try { config.Load(); }
                catch (Exception ex)
                {
                    Logger.LogError(ex.Message);
                    continue;
                }
                Logger.LogDebug($"Loaded config : '{config.GetType().FullOrName()}'", level: LogLevel.Trace);
            }
        }

        /// <summary>
        /// Saves all registered configurations by calling <see cref="ISOSConfig.Save"/> on each one.
        /// </summary>
        /// <remarks>
        /// Iterates over all configs retrieved via <c>API.GetAllConfigs()</c>.
        /// If a config's <see cref="ISOSConfig.Save"/> throws an exception, it is caught, logged via
        /// <see cref="Logger.LogError"/>, and execution continues to the next config.
        /// </remarks>
        public static void SaveConfigs()
        {
            foreach (var config in API.GetAllConfigs())
            {
                try { config.Save(); }
                catch (Exception ex)
                {
                    Logger.LogError(ex.Message);
                    continue;
                }
                Logger.LogDebug($"Saved config : '{config.GetType().FullOrName()}'", level: LogLevel.Trace);
            }
        }

        /// <summary>
        /// Resets all registered configurations by calling <see cref="ISOSConfig.Reset"/> on each one.
        /// </summary>
        /// <remarks>
        /// Iterates over all configs retrieved via <c>API.GetAllConfigs()</c>.
        /// Note: The default implementation of <see cref="ISOSConfig.Reset"/> does nothing and returns <c>false</c>.
        /// If a config overrides this method, it should reset its settings to default values.
        /// If a config's <see cref="ISOSConfig.Reset"/> throws an exception, it is caught, logged via
        /// <see cref="Logger.LogError"/>, and execution continues to the next config.
        /// The misspelling "Reseted" in the original debug log is intentional (legacy).
        /// </remarks>
        public static void ResetConfigs()
        {
            foreach (var config in API.GetAllConfigs())
            {
                try { config.Reset(); }
                catch (Exception ex)
                {
                    Logger.LogError(ex.Message);
                    continue;
                }
                Logger.LogDebug($"Reseted config to defaults : '{config.GetType().FullOrName()}'", level: LogLevel.Trace);
            }
        }

        #endregion

        #region General Helpers

        /// <summary>
        /// Adds a button to a <see cref="GUILayoutBuilder"/> that, when clicked, resets and saves the associated <see cref="ISOSConfig"/> section.
        /// </summary>
        /// <param name="l">The layout builder to which the button will be added.</param>
        /// <param name="cfg">The configuration section to reset and save when the button is clicked.</param>
        /// <param name="text">Optional custom text for the button. If <c>null</c>, uses the default text
        /// "sos.config.reset_section" (localized "Reset Section Defaults").</param>
        /// <param name="onClick">Optional additional action to perform after resetting and saving the config.</param>
        /// <param name="tooltip">Optional tool tip for the button. If <c>null</c>, no tool tip is set.</param>
        /// <param name="color">Optional button color. If <c>null</c>, uses the default (IndianRed with 0.8 alpha).</param>
        /// <param name="style">Optional button style. If <c>null</c>, uses "GUIButtonSmall".</param>
        /// <remarks>
        /// The button click handler calls <see cref="ISOSConfig.Reset"/>, then <see cref="ISOSConfig.Save"/>,
        /// and finally <see cref="Profiles.ProfileHelper.RefreshSettings"/> to refresh the settings UI.
        /// </remarks>
        public static void ButtonToResetSection(this GUILayoutBuilder l, ISOSConfig cfg, string? text = null, Action? onClick = null, string? tooltip = null, Color? color = null, string? style = null)
        {
            Action onClickFinal;
            if (onClick != null) onClickFinal = onClick;
            else onClickFinal = () =>
            {
                cfg.Reset();
                cfg.Save();
                Profiles.ProfileHelper.RefreshSettings(); //TODO: Revisar para hacer esta llamada más limpia.
            };
            l.Button(
                text: text ?? Texts.Get("sos.config.reset_section", "Reset Section Defaults").Value,
                onClick: onClickFinal,
                tooltip: tooltip,
                color: color ?? (Color.IndianRed * 0.8f),
                style: style ?? "GUIButtonSmall"
            );
        }

        /// <summary>
        /// Converts a comma-separated string value to a <see cref="HashSet{T}"/>.
        /// </summary>
        /// <param name="csv">The comma-separated string. If <c>null</c> or empty, returns an empty <see cref="HashSet{T}"/>.</param>
        /// <returns>A <see cref="HashSet{T}"/> containing the trimmed terms from the CSV string.</returns>
        /// <remarks>
        /// Entries are split by comma and trimmed. Empty entries (from consecutive commas or leading/trailing commas)
        /// are included as empty strings unless the framework's default behavior excludes them.
        /// </remarks>
        public static HashSet<string> CsvToHashSet(string? csv)
        {
            if (string.IsNullOrEmpty(csv)) return [];
            return [.. csv.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)];
        }

        /// <summary>
        /// Converts a comma-separated string value to a <see cref="List{T}"/>.
        /// </summary>
        /// <param name="csv">The comma-separated string. If <c>null</c> or empty, returns an empty <see cref="List{T}"/>.</param>
        /// <returns>A <see cref="List{T}"/> containing the trimmed terms from the CSV string.</returns>
        /// <remarks>
        /// Entries are split by comma and trimmed. Empty entries (from consecutive commas or leading/trailing commas)
        /// are included as empty strings unless the framework's default behavior excludes them.
        /// </remarks>
        public static List<string> CsvToList(string? csv)
        {
            if (string.IsNullOrEmpty(csv)) return [];
            return [.. csv.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)];
        }

        /// <summary>
        /// Attempts to initialize a configuration setting by name, retrieving it from the config service.
        /// </summary>
        /// <typeparam name="T">The type of the setting to retrieve; must implement <see cref="ISettingBase"/>.</typeparam>
        /// <param name="name">The name of the configuration setting to look up.</param>
        /// <param name="setting">When this method returns <c>true</c>, contains the retrieved setting; otherwise, the default value for <typeparamref name="T"/>.</param>
        /// <param name="configService">The configuration service used to look up the setting.</param>
        /// <param name="package">The content package from which to retrieve the config.</param>
        /// <param name="onValueChanged">Optional action to invoke when the setting's value changes. Subscribed via
        /// <see cref="ISettingBase.OnValueChanged"/>. In DEBUG mode, also logs the change via <see cref="Logger.LogDebug"/>.</param>
        /// <returns><c>true</c> if the setting was successfully retrieved; <c>false</c> if the config was not found.</returns>
        /// <remarks>
        /// If the config is not found, a warning is logged via <see cref="Logger.LogError"/> and <c>false</c> is returned.
        /// The <paramref name="onValueChanged"/> delegate is subscribed to the setting's change events, allowing
        /// automatic logging or additional processing on value changes.
        /// </remarks>
        public static bool TryInitConfig<T>(string name, [NotNullWhen(true)] out T setting, IConfigService configService, ContentPackage package, Action<ISettingBase>? onValueChanged = null)
                where T : ISettingBase
        {
            if (!configService.TryGetConfig(package, name, out setting))
            {
                Logger.LogError($"Failed to find config named {name}!");
                return false;
            }
            if (onValueChanged != null) setting.OnValueChanged += onValueChanged;
#if DEBUG
            setting.OnValueChanged += setting => Logger.LogDebug($"Changed: {setting.InternalName} To: {setting.GetStringValue(),128}", level: LogLevel.Trace);
#endif
            return true;
        }

        #endregion
    }
}